namespace faiss {

/** CSR-based inverted lists for RecJPQPrune.
 *
 * M splits × B sub-item IDs per split → M*B posting lists.
 * list_id = split * B + sub_item_id
 * offsets has M*B+1 entries; list items are item_ids[offsets[id]..offsets[id+1]].
 * Items are stored as internal positions in ascending order (by construction).
 */
struct RecJPQInvertedLists {
    size_t M = 0, B = 0;

    std::vector<size_t> offsets;   ///< M*B+1
    std::vector<idx_t> item_ids;   ///< N entries total

    /// Two-pass CSR construction from the N×M item-code matrix (row-major, uint8).
    void build(const uint8_t* item_codes, size_t N, size_t M, size_t B);

    void clear();

    /// Number of items in the posting list for (split, sub_item_id).
    size_t list_size(size_t split, size_t sub_item_id) const;

    /// Pointer to the first item in the posting list (valid if list_size>0).
    const idx_t* get_list(size_t split, size_t sub_item_id) const;

    /// [begin, end) half-open range of item positions.
    std::pair<const idx_t*, const idx_t*> get_list_range(
        size_t split, size_t sub_item_id) const;

    /// Total number of postings = N * M.
    size_t total_entries() const { return item_ids.size(); }
};
}
