TEST(IndexRecJPQPrune, ResetAndRebuild) {
    const size_t M = 2, B = 8, ds = 4;
    auto data1 = make_recjpq(M, B, ds, 100, 118);
    auto data2 = make_recjpq(M, B, ds, 150, 119);
